import React, { useState } from 'react';
import { Copy, ClipboardCheck, Users, Zap, Search, Settings, Check, Shuffle, Info, ToggleLeft, ToggleRight, HelpCircle, RotateCcw } from 'lucide-react';
import { useDraftStore } from '../store/useDraftStore';
import { DRAFT_RULESETS } from '../constants/draftRules';

const DraftLobby = ({ formats = [] }) => {
  const { 
    peerId, hostId, draftStatus, initHost, joinRoom, startDraft, isHost, players, 
    applyConfig, pointLimit, maxTeamSize,
    isRandomizedDraft, setRandomizedDraft,
    isCyclingDraft, setCyclingDraft,
    isPityStunfisk, setPityStunfisk,
    selectedGen, setSelectedGen,
    selectedRuleSet, setSelectedRuleSet,
    customDraftSettings, setCustomDraftSettings
  } = useDraftStore();
  const [joinId, setJoinId] = useState('');
  const [copied, setCopied] = useState(false);
  const [draftConfig, setDraftConfig] = useState('');
  const [configApplied, setConfigApplied] = useState(false);
  const [showRulePhilosophy, setShowRulePhilosophy] = useState(null);

  const handleCopyId = () => {
    navigator.clipboard.writeText(peerId);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleApplyConfig = () => {
    if (!draftConfig) return;
    const success = applyConfig(draftConfig);
    if (success) {
      setConfigApplied(true);
      setTimeout(() => setConfigApplied(false), 2000);
      setDraftConfig('');
    } else {
      alert('Invalid configuration format. Please ensure it is valid JSON.');
    }
  };

  if (draftStatus === 'idle') {
    return (
      <div className="max-w-4xl mx-auto py-12 px-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 border border-slate-200">
          <div className="flex flex-col md:flex-row gap-12 items-center">
            <div className="flex-1 space-y-6">
              <div className="inline-flex p-3 bg-blue-100 text-blue-600 rounded-2xl">
                <Users size={32} />
              </div>
              <h2 className="text-3xl font-extrabold text-slate-800">Draft Mode</h2>
              <p className="text-slate-500 leading-relaxed">
                Connect with another player to draft your teams in real-time. 
                Manage your points, pick your Pokemon, and select their Tera Types.
              </p>
              <div className="pt-4 space-y-3">
                <button 
                  onClick={initHost}
                  className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2"
                >
                  <Zap size={20} /> Create Draft Room
                </button>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Search className="h-5 w-5 text-slate-400" />
                  </div>
                  <input
                    type="text"
                    placeholder="Enter Friend's ID to Join..."
                    className="w-full pl-10 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium"
                    value={joinId}
                    onChange={(e) => setJoinId(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && joinId && joinRoom(joinId)}
                  />
                  {joinId && (
                    <button 
                      onClick={() => joinRoom(joinId)}
                      className="absolute right-2 top-2 bottom-2 px-4 bg-slate-800 text-white rounded-lg text-xs font-bold hover:bg-slate-900 transition-colors"
                    >
                      JOIN
                    </button>
                  )}
                </div>
              </div>
            </div>
            <div className="flex-1 w-full max-w-sm">
              <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 space-y-4">
                <h4 className="font-bold text-slate-700 flex items-center gap-2">
                  <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                  Multiplayer Draft
                </h4>
                <ul className="space-y-3">
                  {[
                    'Real-time P2P connection',
                    'Alternating turn-based picking',
                    'Shared Pokemon pool',
                    'Point budget management',
                    'Tera Type selection'
                  ].map((feature, i) => (
                    <li key={i} className="flex items-center gap-3 text-sm text-slate-600 font-medium">
                      <div className="w-5 h-5 bg-green-100 text-green-600 rounded-full flex items-center justify-center text-[10px]">✓</div>
                      {feature}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (draftStatus === 'hosting' || draftStatus === 'joining' || draftStatus === 'connected') {
    return (
      <div className="max-w-xl mx-auto py-12 px-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 border border-slate-200 text-center space-y-8">
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800">
              {draftStatus === 'connected' ? 'Ready to Start!' : 'Waiting for Players...'}
            </h2>
            <div className="flex flex-col gap-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Players in Lobby ({players.length}/6)</span>
              {players.map((p, i) => (
                <div key={i} className="flex items-center justify-between bg-white px-3 py-2 rounded-lg border border-slate-100 shadow-sm">
                  <span className="text-sm font-bold text-slate-700">{p.name} {p.id === peerId ? '(You)' : ''}</span>
                  <span className="text-[10px] bg-blue-100 text-blue-600 px-2 py-0.5 rounded font-black uppercase">Slot {p.index + 1}</span>
                </div>
              ))}
              {players.length < 2 && (
                <p className="text-xs text-slate-400 italic py-2">Waiting for at least one more player...</p>
              )}
            </div>
            {!isHost && draftStatus === 'connected' && (
              <p className="text-slate-500 font-medium text-sm">
                Connected to Host. Waiting for them to start the draft.
              </p>
            )}
          </div>

          <div className="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-300 relative group text-left">
            <span className="absolute -top-3 left-4 px-2 bg-white text-[10px] font-bold text-slate-400 uppercase tracking-widest border border-slate-100 rounded">
              Room ID
            </span>
            <div className="flex items-center justify-between gap-4">
              <p className="text-lg font-mono font-bold text-slate-700 break-all select-all">
                {isHost ? peerId : hostId}
              </p>
              {isHost && (
                <button 
                  onClick={handleCopyId}
                  className="flex-shrink-0 p-2 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-blue-400 hover:text-blue-600 transition-all font-bold text-sm"
                >
                  {copied ? <ClipboardCheck size={18} className="text-green-500" /> : <Copy size={18} />}
                </button>
              )}
            </div>
          </div>

          {isHost && (
            <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200 text-left space-y-6">
              <div className="flex items-center justify-between">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                  <Settings size={14} /> Draft Settings
                </h4>
                <div className="flex items-center gap-3">
                  {/* Generation Selector */}
                  <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-lg px-2 shadow-sm h-8">
                    <span className="text-[10px] font-black text-slate-400 uppercase">Gen:</span>
                    <select 
                      value={selectedGen} 
                      onChange={(e) => setSelectedGen(e.target.value)}
                      className="bg-transparent border-none text-[10px] font-bold focus:ring-0 outline-none cursor-pointer"
                    >
                      {formats.length > 0 ? (
                        formats.map(f => (
                          <option key={f.shorthand} value={f.shorthand}>{f.name}</option>
                        ))
                      ) : (
                        <option value="sv">Scarlet/Violet</option>
                      )}
                    </select>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <button 
                      onClick={() => setRandomizedDraft(!isRandomizedDraft)}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                        isRandomizedDraft 
                          ? "bg-blue-600 text-white shadow-md shadow-blue-100" 
                          : "bg-white border border-slate-200 text-slate-400 hover:border-slate-300"
                      }`}
                    >
                      <Shuffle size={12} />
                      Randomized: {isRandomizedDraft ? 'ON' : 'OFF'}
                    </button>

                    <button 
                      onClick={() => setCyclingDraft(!isCyclingDraft)}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                        isCyclingDraft 
                          ? "bg-blue-600 text-white shadow-md shadow-blue-100" 
                          : "bg-white border border-slate-200 text-slate-400 hover:border-slate-300"
                      }`}
                      title="A new pool is generated after every round of picks"
                    >
                      <RotateCcw size={12} />
                      Cycling: {isCyclingDraft ? 'ON' : 'OFF'}
                    </button>

                    <button 
                      onClick={() => setPityStunfisk(!isPityStunfisk)}
                      className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                        isPityStunfisk 
                          ? "bg-blue-600 text-white shadow-md shadow-blue-100" 
                          : "bg-white border border-slate-200 text-slate-400 hover:border-slate-300"
                      }`}
                      title="Get a Stunfisk if you run out of points"
                    >
                      <Zap size={12} />
                      Pity Stunfisk: {isPityStunfisk ? 'ON' : 'OFF'}
                    </button>
                  </div>
                </div>
              </div>

              {isRandomizedDraft ? (
                <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                  <div className="grid grid-cols-1 gap-3">
                    {DRAFT_RULESETS.map((rule) => (
                      <div 
                        key={rule.id}
                        onClick={() => setSelectedRuleSet(rule.id)}
                        className={`p-3 rounded-xl border-2 cursor-pointer transition-all relative group ${
                          selectedRuleSet === rule.id 
                            ? "bg-white border-blue-500 shadow-sm" 
                            : "bg-slate-50 border-transparent hover:border-slate-200"
                        }`}
                      >
                        <div className="flex items-center justify-between mb-1">
                          <span className={`text-xs font-black uppercase tracking-tight ${selectedRuleSet === rule.id ? "text-blue-600" : "text-slate-600"}`}>
                            {rule.name}
                          </span>
                          <button 
                            onMouseEnter={() => setShowRulePhilosophy(rule.id)}
                            onMouseLeave={() => setShowRulePhilosophy(null)}
                            className="text-slate-300 hover:text-blue-500 transition-colors"
                          >
                            <HelpCircle size={14} />
                          </button>
                        </div>
                        <p className="text-[10px] text-slate-400 font-medium leading-tight pr-6">
                          {rule.description}
                        </p>
                        
                        {showRulePhilosophy === rule.id && (
                          <div className="absolute z-10 top-full left-0 right-0 mt-2 p-3 bg-slate-800 text-white text-[10px] rounded-lg shadow-xl border border-slate-700 pointer-events-none">
                            <p className="font-bold mb-1 text-blue-300 uppercase tracking-widest">Philosophy</p>
                            {rule.philosophy}
                          </div>
                        )}
                      </div>
                    ))}
                    
                    {/* Custom Mode Toggle */}
                    <div 
                      onClick={() => setSelectedRuleSet('custom')}
                      className={`p-3 rounded-xl border-2 cursor-pointer transition-all ${
                        selectedRuleSet === 'custom' 
                          ? "bg-white border-blue-500 shadow-sm" 
                          : "bg-slate-50 border-transparent hover:border-slate-200"
                      }`}
                    >
                      <span className={`text-xs font-black uppercase tracking-tight block mb-1 ${selectedRuleSet === 'custom' ? "text-blue-600" : "text-slate-600"}`}>
                        Custom Mode
                      </span>
                      <p className="text-[10px] text-slate-400 font-medium leading-tight">
                        Fine-tune your own randomized draft rules.
                      </p>
                    </div>
                  </div>

                  {selectedRuleSet === 'custom' && (
                    <div className="p-4 bg-white rounded-xl border border-slate-200 space-y-4 animate-in zoom-in-95 duration-200">
                      <div className="grid grid-cols-1 gap-4">
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase">Pool Size</label>
                          <input 
                            type="number"
                            min="6"
                            max="30"
                            value={customDraftSettings.poolSize}
                            onChange={(e) => setCustomDraftSettings({ poolSize: parseInt(e.target.value) || 15 })}
                            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold"
                          />
                        </div>
                      </div>
                      
                      <div className="space-y-2">
                        {[
                          { id: 'enforceTierDiversity', label: 'Enforce Tier Diversity', icon: <Shuffle size={10} /> },
                          { id: 'enforceTypeDiversity', label: 'Enforce Type Diversity', icon: <Info size={10} /> },
                          { id: 'balancedTiersOnly', label: 'Balanced Tiers (Within 1 Tier)', icon: <Zap size={10} /> },
                          { id: 'isCyclingDraft', label: 'Cycling Draft (New Pool Each Round)', icon: <RotateCcw size={10} /> },
                          { id: 'pityStunfisk', label: 'Pity Stunfisk (If Out of Points)', icon: <Zap size={10} /> }
                        ].map(toggle => (
                          <button
                            key={toggle.id}
                            onClick={() => setCustomDraftSettings({ [toggle.id]: !customDraftSettings[toggle.id] })}
                            className="w-full flex items-center justify-between p-2 hover:bg-slate-50 rounded-lg transition-colors group"
                          >
                            <span className="text-[10px] font-bold text-slate-600 flex items-center gap-2">
                              {toggle.icon}
                              {toggle.label}
                            </span>
                            {customDraftSettings[toggle.id] ? (
                              <ToggleRight className="text-blue-500" size={20} />
                            ) : (
                              <ToggleLeft className="text-slate-300" size={20} />
                            )}
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              ) : (
                <>
                  <div className="flex gap-3 text-[10px] font-bold text-slate-500">
                    <span className="px-2 py-0.5 bg-white border border-slate-200 rounded">Budget: {pointLimit}</span>
                    <span className="px-2 py-0.5 bg-white border border-slate-200 rounded">Size: {maxTeamSize}</span>
                  </div>
                  <div className="relative">
                    <textarea
                      value={draftConfig}
                      onChange={(e) => setDraftConfig(e.target.value)}
                      className="w-full h-20 p-3 text-[10px] font-mono bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                      placeholder="Paste configuration 'blob' here to override budget/costs..."
                    />
                    <button
                      onClick={handleApplyConfig}
                      disabled={!draftConfig}
                      className={`absolute bottom-2 right-2 px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all shadow-sm flex items-center gap-1 ${
                        configApplied 
                          ? "bg-green-500 text-white" 
                          : draftConfig 
                            ? "bg-slate-800 text-white hover:bg-slate-900" 
                            : "bg-slate-200 text-slate-400 pointer-events-none"
                      }`}
                    >
                      {configApplied ? <Check size={12} /> : null}
                      {configApplied ? 'APPLIED' : 'APPLY CONFIG'}
                    </button>
                  </div>
                </>
              )}
              
              <p className="text-[9px] text-slate-400 italic">
                * {isRandomizedDraft ? "Settings are automatically synced with players." : "Paste the JSON from your Normal Mode settings to use custom points."}
              </p>
            </div>
          )}

          <div className="pt-4">
            {isHost ? (
              <button 
                onClick={startDraft}
                disabled={players.length < 2}
                className="w-full py-4 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 disabled:text-slate-400 text-white rounded-xl font-bold shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2"
              >
                START DRAFT
              </button>
            ) : (
              <div className="py-4 text-sm font-bold text-slate-400 animate-pulse uppercase tracking-widest">
                Waiting for host to start...
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return null;
};

export default DraftLobby;
