import axios from 'axios';
import tierPointsMap from './tierPointsMap.json'; // We'll create this file

// Default CORS proxy to bypass Smogon's CORS policy in a browser environment
const DEFAULT_PROXY = 'https://corsproxy.io/?';

/**
 * Scrapes Smogon Dex for available formats (generations) directly from the browser.
 */
export async function getSmogonFormats(proxyUrl = DEFAULT_PROXY) {
  try {
    const targetUrl = 'https://www.smogon.com/dex/sv/pokemon/';
    const url = `${proxyUrl}${encodeURIComponent(targetUrl)}`;
    
    const response = await axios.get(url);

    const html = response.data;
    const startIndex = html.indexOf('dexSettings =');
    if (startIndex === -1) throw new Error('Could not find dexSettings in HTML');
    
    const jsonStart = html.indexOf('{', startIndex);
    let braceCount = 0;
    let jsonEnd = -1;
    for (let i = jsonStart; i < html.length; i++) {
        if (html[i] === '{') braceCount++;
        else if (html[i] === '}') braceCount--;
        
        if (braceCount === 0) {
            jsonEnd = i + 1;
            break;
        }
    }
    
    if (jsonEnd === -1) throw new Error('Could not parse dexSettings JSON');
    
    const settings = JSON.parse(html.substring(jsonStart, jsonEnd));
    const gensRpc = settings.injectRpcs.find(rpc => rpc[0].includes('dump-gens'));
    
    if (gensRpc && gensRpc[1]) {
        return gensRpc[1].map(g => ({
            name: g.name,
            shorthand: g.shorthand.toLowerCase()
        }));
    }
    
    return [{ name: 'Scarlet/Violet', shorthand: 'sv' }];
  } catch (error) {
    console.error('Error fetching Smogon formats via proxy:', error.message);
    return [{ name: 'Scarlet/Violet', shorthand: 'sv' }];
  }
}

/**
 * Gets specific tiers/formats for a generation (e.g., OU, UU, VGC) from the browser.
 */
export async function getTiersForGen(gen = 'sv', proxyUrl = DEFAULT_PROXY) {
  try {
    const targetUrl = `https://www.smogon.com/dex/${gen}/pokemon/`;
    const url = `${proxyUrl}${encodeURIComponent(targetUrl)}`;
    
    const response = await axios.get(url);

    const html = response.data;
    const startIndex = html.indexOf('dexSettings =');
    if (startIndex === -1) throw new Error('Could not find dexSettings in HTML');
    
    const jsonStart = html.indexOf('{', startIndex);
    let braceCount = 0;
    let jsonEnd = -1;
    for (let i = jsonStart; i < html.length; i++) {
        if (html[i] === '{') braceCount++;
        else if (html[i] === '}') braceCount--;
        
        if (braceCount === 0) {
            jsonEnd = i + 1;
            break;
        }
    }
    
    if (jsonEnd === -1) throw new Error('Could not parse dexSettings JSON');
    
    const settings = JSON.parse(html.substring(jsonStart, jsonEnd));
    const basicsRpc = settings.injectRpcs.find(rpc => rpc[0].includes('dump-basics'));
    
    if (!basicsRpc || !basicsRpc[1]) return [];
    
    const basics = typeof basicsRpc[1] === 'string' ? JSON.parse(basicsRpc[1]) : basicsRpc[1];
    if (!basics.formats) return [];

    const allowedTiers = ["OU", "Uber", "Ubers", "UU", "RU", "NU", "PU", "ZU", "OverUsed", "UnderUsed", "RarelyUsed", "NeverUsed", "ZeroUsed", "DOU", "DUU", "DUber", "VGC", "Doubles", "Doubles OU", "Doubles UU", "Doubles Ubers", "Untiered"];
    const genUpper = gen.toUpperCase();
    
    const tiers = basics.formats
      .filter(f => f.genfamily && f.genfamily.includes(genUpper))
      .filter(f => allowedTiers.includes(f.name) || allowedTiers.includes(f.shorthand))
      .map(f => ({
        name: f.name,
        shorthand: f.shorthand
      }));

    // Add Untiered if not present
    if (!tiers.find(t => t.shorthand === 'Untiered')) {
      tiers.push({ name: 'Untiered', shorthand: 'Untiered' });
    }

    return tiers;
  } catch (error) {
    console.error(`Error fetching tiers for gen ${gen} via proxy:`, error.message);
    return [];
  }
}

/**
 * Helper to fetch a specific format's Pokemon list from the browser.
 */
async function fetchFormatPokemon(gen, formatAlias, proxyUrl = DEFAULT_PROXY) {
  try {
    const targetUrl = `https://www.smogon.com/dex/${gen}/formats/${formatAlias}/`;
    const url = `${proxyUrl}${encodeURIComponent(targetUrl)}`;
    const response = await axios.get(url);

    const html = response.data;
    const startIndex = html.indexOf('dexSettings =');
    if (startIndex === -1) return [];
    
    const jsonStart = html.indexOf('{', startIndex);
    let braceCount = 0;
    let jsonEnd = -1;
    for (let i = jsonStart; i < html.length; i++) {
        if (html[i] === '{') braceCount++;
        else if (html[i] === '}') braceCount--;
        
        if (braceCount === 0) {
            jsonEnd = i + 1;
            break;
        }
    }
    
    if (jsonEnd === -1) return [];
    
    const settings = JSON.parse(html.substring(jsonStart, jsonEnd));
    const formatRpc = settings.injectRpcs.find(rpc => rpc[0].includes('dump-format'));
    
    if (formatRpc && formatRpc[1]) {
        const data = typeof formatRpc[1] === 'string' ? JSON.parse(formatRpc[1]) : formatRpc[1];
        return data.pokemon_with_strategies || [];
    }
    
    return [];
  } catch (error) {
    console.error(`Error fetching format ${formatAlias} via proxy:`, error.message);
    return [];
  }
}

/**
 * Scrapes Smogon Dex for Pokemon tier information for a specific generation from the browser.
 */
export async function scrapeSmogonTiers(gen = 'sv', selectedTier = null, customTierPoints = null, formatType = 'singles', proxyUrl = DEFAULT_PROXY) {
  try {
    const targetUrl = `https://www.smogon.com/dex/${gen}/pokemon/`;
    const url = `${proxyUrl}${encodeURIComponent(targetUrl)}`;
    
    const response = await axios.get(url);

    const html = response.data;
    const startIndex = html.indexOf('dexSettings =');
    if (startIndex === -1) throw new Error('Could not find dexSettings in HTML');
    
    const jsonStart = html.indexOf('{', startIndex);
    let braceCount = 0;
    let jsonEnd = -1;
    for (let i = jsonStart; i < html.length; i++) {
        if (html[i] === '{') braceCount++;
        else if (html[i] === '}') braceCount--;
        
        if (braceCount === 0) {
            jsonEnd = i + 1;
            break;
        }
    }
    
    if (jsonEnd === -1) throw new Error('Could not parse dexSettings JSON');
    
    const settings = JSON.parse(html.substring(jsonStart, jsonEnd));
    const pokemonRpc = settings.injectRpcs.find(rpc => 
      rpc[0].includes('dump-pokemon') || rpc[0].includes('dump-basics')
    );
    
    let dexData = null;
    if (pokemonRpc && pokemonRpc[1]) {
        dexData = typeof pokemonRpc[1] === 'string' ? JSON.parse(pokemonRpc[1]) : pokemonRpc[1];
    }

    if (!dexData || !dexData.pokemon) {
      throw new Error(`Could not extract Smogon Dex data for gen ${gen} via proxy.`);
    }

    const pokemonList = dexData.pokemon;
    const results = {};

    // For Doubles, we need to fetch multiple formats because they aren't in dump-basics
    let doublesMapping = {};
    if (formatType === 'doubles') {
      const [doublesOU, doublesUU, doublesUbers, vgc] = await Promise.all([
        fetchFormatPokemon(gen, 'doubles', proxyUrl),
        fetchFormatPokemon(gen, 'doubles-uu', proxyUrl),
        fetchFormatPokemon(gen, 'doubles-ubers', proxyUrl),
        fetchFormatPokemon(gen, 'vgc', proxyUrl)
      ]);

      doublesUbers.forEach(name => doublesMapping[name] = 'DUber');
      doublesOU.forEach(name => { if (!doublesMapping[name]) doublesMapping[name] = 'DOU'; });
      doublesUU.forEach(name => { if (!doublesMapping[name]) doublesMapping[name] = 'DUU'; });
      vgc.forEach(name => { if (!doublesMapping[name]) doublesMapping[name] = 'VGC'; });

      // If gen is SV, we can guess some DUber tiers based on singles Uber availability
      if (gen === 'sv') {
        const potentialDUbers = pokemonList.filter(p => p.formats && p.formats.includes('Uber')).map(p => p.name);
        potentialDUbers.forEach(name => { if (!doublesMapping[name]) doublesMapping[name] = 'DUber'; });
      }
    }
    
    const singlesTierOrder = ["AG", "Uber", "OU", "UUBL", "UU", "RUBL", "RU", "NUBL", "NU", "PUBL", "PU", "ZUBL", "ZU", "Untiered"];
    const doublesTierOrder = ["DUber", "DOU", "DUU", "VGC", "Untiered"];
    const tierOrder = formatType === 'doubles' ? doublesTierOrder : singlesTierOrder;

    const singlesAllowedTiers = ["AG", "Uber", "Ubers", "OU", "UUBL", "UU", "RUBL", "RU", "NUBL", "NU", "PUBL", "PU", "ZUBL", "ZU", "OverUsed", "UnderUsed", "RarelyUsed", "NeverUsed", "ZeroUsed", "Untiered"];
    const doublesAllowedTiers = ["DUber", "DOU", "DUU", "VGC", "Doubles OU", "Doubles UU", "Doubles Ubers", "Untiered"];
    const allowedTiers = formatType === 'doubles' ? doublesAllowedTiers : singlesAllowedTiers;

    // Full name to shorthand mapping for points
    const tierNameMap = {
      'OverUsed': 'OU',
      'UnderUsed': 'UU',
      'RarelyUsed': 'RU',
      'NeverUsed': 'NU',
      'ZeroUsed': 'ZU',
      'Ubers': 'Uber',
      'Doubles OU': 'DOU',
      'Doubles': 'DOU',
      'Doubles UnderUsed': 'DUU',
      'Doubles UU': 'DUU',
      'Doubles Ubers': 'DUber',
      'Doubles Uber': 'DUber'
    };

    pokemonList.forEach(p => {
      if (p.isNonstandard && p.isNonstandard !== 'Standard') return;
      if (p.formats && p.formats.includes('CAP')) return;

      const name = p.name;
      
      // For Doubles, try to find a doubles-specific format in p.formats first
      let tier = 'Untiered';
      if (formatType === 'doubles') {
        // First check our mapping from format-specific pages
        tier = doublesMapping[name] || 'Untiered';
        
        // Fallback 1: check p.formats just in case Smogon updated it
        if (tier === 'Untiered') {
          const doublesFormat = p.formats?.find(f => doublesAllowedTiers.includes(f));
          if (doublesFormat) tier = doublesFormat;
        }

        // Fallback 2: if no doubles tier found, use the singles tier as requested by user
        if (tier === 'Untiered') {
          tier = p.tier || p.formats?.find(f => singlesAllowedTiers.includes(f)) || 'Untiered';
        }
      } else {
        // For singles, use p.tier or the first allowed singles format
        tier = p.tier || p.formats?.find(f => singlesAllowedTiers.includes(f)) || 'Untiered';
      }

      // Even if "All Tiers" is selected, we only want to show Pokemon from the allowed formats
      const allAllowedTiers = [...singlesAllowedTiers, ...doublesAllowedTiers];
      if (!allAllowedTiers.includes(tier) && tier !== 'Untiered') return;
      
      // If a specific tier is selected, only include Pokemon that are exactly in that tier
      if (selectedTier) {
        // Map current tier to its shorthand for comparison if necessary
        const currentShorthand = tierNameMap[tier] || tier;
        const selectedShorthand = tierNameMap[selectedTier] || selectedTier;
        
        if (currentShorthand !== selectedShorthand) {
          return;
        }
      }
      
      const shorthandTier = tierNameMap[tier] || tier;
      
      const cost = (customTierPoints && customTierPoints[shorthandTier] !== undefined) 
        ? customTierPoints[shorthandTier] 
        : (tierPointsMap[shorthandTier] || 0);
      
      results[name] = { 
        cost, 
        id: p.number || p.oob?.dex_number,
        types: p.types || [],
        isFullyEvolved: !p.evos || p.evos.length === 0
      };
    });

    return results;
  } catch (error) {
    console.error('Error fetching Smogon tiers via proxy:', error.message);
    throw error;
  }
}
