/**
 * Generates a PokeAPI sprite URL for a given Pokemon ID or name.
 * 
 * @param {number|string} idOrName - The ID (number) or name (string) of the Pokemon.
 * @returns {string} - The URL to the Pokemon's sprite.
 */
export const getPokemonSpriteUrl = (idOrName) => {
  if (!idOrName) return '';

  // If we have an ID, we can get the sprite from PokeAPI GitHub repository
  if (typeof idOrName === 'number' || !isNaN(Number(idOrName))) {
    const id = Number(idOrName);
    // Standard sprite
    // return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`;
    
    // Better quality Home sprite
    return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/home/${id}.png`;
  }

  // Fallback to name-based URL if ID is not available
  const formattedName = idOrName
    .toLowerCase()
    .replace(/[.:]/g, '')
    .replace(/[']/g, '')
    .replace(/\s+/g, '-')
    .replace(/♀/g, '-f')
    .replace(/♂/g, '-m');

  // img.pokemondb.net is reliable for name-based lookups
  return `https://img.pokemondb.net/sprites/home/normal/${formattedName}.png`;
};
