import React, { useState, useEffect } from 'react';
import { useTeamStore } from './store/useTeamStore';
import { useDraftStore } from './store/useDraftStore';
import TeamMember from './components/TeamMember';
import PokemonBrowser from './components/PokemonBrowser';
import SettingsModal from './components/SettingsModal';
import TeraTypeModal from './components/TeraTypeModal';
import DraftLobby from './components/DraftLobby';
import DraftBoard from './components/DraftBoard';
import DraftFinishedScreen from './components/DraftFinishedScreen';
import { Globe, Loader2, Settings, Zap, Users } from 'lucide-react';
import axios from 'axios';
import * as SmogonFrontend from './services/smogonService';

const API_BASE_URL = process.env.NODE_ENV === 'production' 
  ? null // In production, we'll default to frontend scraping
  : 'http://localhost:5001/api';

function App() {
  const [appMode, setAppMode] = useState('normal'); // 'normal' or 'draft'
  const { 
    team, 
    pointList,
    setPointList,
    setSelectedMemberIndex,
    isBrowserOpen,
    tierPoints,
    formatType,
    setFormatType,
    resetTeam
  } = useTeamStore();

  const { 
    draftStatus, 
    resetDraft, 
    setIsBrowserOpen: setDraftBrowserOpen,
    draftTeams,
    players,
    peerId,
    pointLimit: draftPointLimit
  } = useDraftStore();

  const [isScraping, setIsScraping] = useState(false);
  const [formats, setFormats] = useState([]);
  const [tiers, setTiers] = useState([]);
  const [selectedGen, setSelectedGen] = useState('sv');
  const [selectedTier, setSelectedTier] = useState('');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Sync team costs when gen, format, or tier changes
  useEffect(() => {
    const cacheKey = `${selectedGen}_${formatType}_${selectedTier || 'all'}`;
    const currentList = pointList[cacheKey];
    
    if (currentList) {
      // Create a set of updated members
      const updatedMembers = team.members.map(m => {
        if (!m.name) return m;
        const entry = currentList[m.name];
        return {
          ...m,
          cost: entry ? (typeof entry === 'object' ? entry.cost : entry) : 0,
          id: entry && typeof entry === 'object' ? entry.id : m.id
        };
      });
      
      // Only update if something actually changed to avoid infinite loops
      const hasChanged = JSON.stringify(updatedMembers) !== JSON.stringify(team.members);
      if (hasChanged) {
        // We use a custom action or setTeam
        // For now let's assume updateMember is enough or we need a bulk update
        // Since we want to update the whole team:
        const { setTeam } = useTeamStore.getState();
        setTeam({ ...team, members: updatedMembers });
      }
    }
  }, [selectedGen, formatType, selectedTier, pointList]);

  // Clear team when format changes
  useEffect(() => {
    resetTeam();
  }, [formatType, resetTeam]);

  useEffect(() => {
    const fetchFormats = async () => {
      try {
        if (API_BASE_URL) {
          const response = await axios.get(`${API_BASE_URL}/formats`);
          if (response.data && response.data.success) {
            setFormats(response.data.formats);
            return;
          }
        }
        
        // Fallback or Production: use frontend scraper
        const data = await SmogonFrontend.getSmogonFormats();
        setFormats(data);
      } catch (err) {
        console.error('Error fetching formats:', err);
        // Ensure we at least have some formats
        if (formats.length === 0) {
          setFormats([{ name: 'Scarlet/Violet', shorthand: 'sv' }]);
        }
      }
    };
    fetchFormats();
  }, []);

  useEffect(() => {
    const fetchTiers = async () => {
      if (!selectedGen) return;
      try {
        if (API_BASE_URL) {
          const response = await axios.get(`${API_BASE_URL}/tiers/${selectedGen}`);
          if (response.data && response.data.success) {
            setTiers(response.data.tiers);
            setSelectedTier('');
            return;
          }
        }

        // Fallback or Production: use frontend scraper
        const data = await SmogonFrontend.getTiersForGen(selectedGen);
        setTiers(data);
        setSelectedTier('');
      } catch (err) {
        console.error('Error fetching tiers:', err);
      }
    };
    fetchTiers();
  }, [selectedGen, formatType]);

  const filteredTiers = tiers.filter(t => {
    const isDoublesTier = t.shorthand.startsWith('D') || t.shorthand === 'VGC' || t.name.toLowerCase().includes('doubles');
    return formatType === 'doubles' ? isDoublesTier : !isDoublesTier;
  });

  const myIndex = players.findIndex(p => p.id === peerId);
  const totalPoints = appMode === 'draft' && myIndex !== -1 && draftTeams[myIndex]
    ? draftTeams[myIndex].reduce((sum, m) => sum + (m.cost || 0), 0)
    : team.members.reduce((sum, m) => sum + (m.cost || 0), 0);
  
  const currentPointLimit = appMode === 'draft' ? draftPointLimit : team.pointLimit;

  const handleScrapeTiers = async () => {
    setIsScraping(true);
    try {
      let pointsMap;

      if (API_BASE_URL) {
        try {
          const response = await axios.post(`${API_BASE_URL}/scrape-tiers`, { 
            gen: selectedGen,
            tier: selectedTier,
            tierPoints: tierPoints,
            formatType: formatType
          });
          if (response.data && response.data.success && response.data.pointList) {
            pointsMap = response.data.pointList;
          }
        } catch (backendErr) {
          console.warn('Backend scraping failed, falling back to frontend:', backendErr.message);
        }
      }

      // If backend failed or we are in production
      if (!pointsMap) {
        pointsMap = await SmogonFrontend.scrapeSmogonTiers(selectedGen, selectedTier, tierPoints, formatType);
      }

      if (pointsMap) {
        setPointList(selectedGen, formatType, selectedTier, pointsMap);
        resetTeam();
        const genName = formats.find(f => f.shorthand === selectedGen)?.name || selectedGen;
        const tierName = selectedTier || 'All Tiers';
        alert(`Successfully updated ${Object.keys(pointsMap).length} Pokemon from Smogon ${genName} (${tierName})!`);
      } else {
        throw new Error('Could not retrieve point list');
      }
    } catch (err) {
      console.error(err);
      alert('Error fetching Smogon tiers: ' + err.message);
    } finally {
      setIsScraping(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-4 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-6">
            <div>
              <h1 className="text-xl font-bold text-blue-600">
                Pokemon Point Buy
              </h1>
              <p className="text-slate-500 text-xs">
                Points: <span className={totalPoints > currentPointLimit ? 'text-red-500 font-bold' : 'font-bold text-slate-900'}>
                  {totalPoints}
                </span> / {currentPointLimit}
              </p>
            </div>
            <div className="h-8 w-px bg-slate-200 hidden sm:block"></div>
            <div className="hidden sm:block">
               <span className="text-[10px] font-bold text-slate-400 uppercase block">Status</span>
               <span className="text-xs font-medium">
                 {totalPoints > currentPointLimit ? '⚠️ Over Budget' : '✅ Within Budget'}
               </span>
            </div>
          </div>
          
          <div className="flex gap-2">
            <div className="flex p-0.5 bg-slate-50 rounded-md border border-slate-200 h-[42px] my-auto">
              <button
                onClick={() => { setAppMode('normal'); resetDraft(); }}
                className={`px-3 rounded text-[10px] font-bold transition-all flex flex-col items-center justify-center ${
                  appMode === 'normal' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-slate-400 hover:text-slate-600'
                }`}
                title="Normal Team Builder"
              >
                <Zap size={14} /> Normal
              </button>
              <button
                onClick={() => setAppMode('draft')}
                className={`px-3 rounded text-[10px] font-bold transition-all flex flex-col items-center justify-center ${
                  appMode === 'draft' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-slate-400 hover:text-slate-600'
                }`}
                title="Multiplayer Draft Mode"
              >
                <Users size={14} /> Draft
              </button>
            </div>

            <div className="h-10 w-px bg-slate-200 hidden sm:block"></div>

            <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-lg px-2 shadow-sm">
              <select 
                value={selectedGen} 
                onChange={(e) => setSelectedGen(e.target.value)}
                className="bg-transparent border-none text-sm font-semibold py-2 focus:ring-0 outline-none cursor-pointer"
                disabled={isScraping}
              >
                {formats.length > 0 ? (
                  formats.map(f => (
                    <option key={f.shorthand} value={f.shorthand}>{f.name}</option>
                  ))
                ) : (
                  <option value="sv">Scarlet/Violet</option>
                )}
              </select>
              
              <div className="h-6 w-px bg-slate-200"></div>

              <div className="flex p-0.5 bg-slate-50 rounded-md border border-slate-200 h-[36px] my-auto">
                <button
                  onClick={() => setFormatType('singles')}
                  disabled={isScraping}
                  className={`px-2 rounded text-[10px] font-bold transition-all ${
                    formatType === 'singles' 
                      ? 'bg-white text-blue-600 shadow-sm' 
                      : 'text-slate-400 hover:text-slate-600'
                  }`}
                >
                  S
                </button>
                <button
                  onClick={() => setFormatType('doubles')}
                  disabled={isScraping}
                  className={`px-2 rounded text-[10px] font-bold transition-all ${
                    formatType === 'doubles' 
                      ? 'bg-white text-blue-600 shadow-sm' 
                      : 'text-slate-400 hover:text-slate-600'
                  }`}
                >
                  D
                </button>
              </div>

              <div className="h-6 w-px bg-slate-200"></div>
              
              <select 
                value={selectedTier} 
                onChange={(e) => setSelectedTier(e.target.value)}
                className="bg-transparent border-none text-sm font-semibold py-2 focus:ring-0 outline-none cursor-pointer max-w-[120px]"
                disabled={isScraping || filteredTiers.length === 0}
              >
                <option value="">All Tiers</option>
                {filteredTiers.map(t => (
                  <option key={t.shorthand} value={t.shorthand}>{t.name}</option>
                ))}
              </select>

              <button 
                onClick={handleScrapeTiers}
                disabled={isScraping}
                className={`p-1 text-blue-600 hover:bg-slate-50 disabled:opacity-50 transition-colors rounded-md ${
                  !pointList[`${selectedGen}_${formatType}_${selectedTier || 'all'}`] ? 'animate-pulse bg-blue-50 ring-2 ring-blue-400' : ''
                }`}
                title="Download Tiers for Selected Gen & Format"
              >
                {isScraping ? <Loader2 size={16} className="animate-spin" /> : <div className="flex items-center gap-1 px-1"><Globe size={16} /><span className="text-[10px] font-bold uppercase hidden md:inline">Download Tiers</span></div>}
              </button>
            </div>
            
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="p-2 bg-white border border-slate-200 rounded-lg shadow-sm hover:bg-slate-50 transition-colors text-slate-600"
              title="Settings"
            >
              <Settings size={20} />
            </button>
          </div>
        </div>
      </header>
      
      <main className="flex-1">
        {appMode === 'normal' ? (
          <div className="max-w-7xl mx-auto p-8">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              {team.members.map((member, index) => (
                <TeamMember
                  key={index}
                  index={index}
                  member={member}
                  onClick={setSelectedMemberIndex}
                />
              ))}
            </div>

            <div className="mt-12 max-w-2xl mx-auto bg-white p-6 rounded-lg border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold mb-3 text-slate-800 flex items-center gap-2">
                <Zap size={20} className="text-blue-500" />
                What is Pokemon Point Buy?
              </h2>
              <p className="text-slate-600 text-sm leading-relaxed mb-4">
                Pokemon Point Buy is a team-building format that adds a layer of strategy by assigning a point cost to each Pokemon based on its Smogon tier.
                Rather than simply picking the strongest available options, you must manage a limited budget (default 50 points) to build a balanced team of {team.maxTeamSize || 6}.
                Custom limits (like one per tier) can be applied in the settings to further refine your format.
              </p>
              <div className="grid grid-cols-2 gap-4 text-xs">
                <div className="space-y-1 text-slate-500">
                  <p><span className="font-bold text-slate-700">AG:</span> 40 pts</p>
                  <p><span className="font-bold text-slate-700">Uber / DUber:</span> 30 pts</p>
                  <p><span className="font-bold text-slate-700">OU / DOU:</span> 12 pts</p>
                  <p><span className="font-bold text-slate-700">UUBL / VGC:</span> 10 pts</p>
                </div>
                <div className="space-y-1 text-slate-500">
                  <p><span className="font-bold text-slate-700">UU / DUU:</span> 8 pts</p>
                  <p><span className="font-bold text-slate-700">RU:</span> 6 pts</p>
                  <p><span className="font-bold text-slate-700">NU:</span> 4 pts</p>
                  <p><span className="font-bold text-slate-700">PU / ZU / LC:</span> 0-2 pts</p>
                </div>
              </div>
              <p className="text-slate-400 text-[10px] mt-4 italic">
                * Costs and limits can be customized in the settings. Use the "Download Tiers" button to fetch latest Smogon data.
              </p>
            </div>
          </div>
        ) : (
          <div className="max-w-7xl mx-auto">
            {draftStatus === 'finished' ? (
              <DraftFinishedScreen />
            ) : draftStatus === 'drafting' ? (
              <DraftBoard />
            ) : (
              <DraftLobby formats={formats} />
            )}
          </div>
        )}
      </main>

      {isBrowserOpen && (
        <PokemonBrowser 
          selectedGen={selectedGen} 
          formatType={formatType} 
          selectedTier={selectedTier} 
        />
      )}

      {/* Draft Mode Browser */}
      {appMode === 'draft' && (draftStatus === 'drafting' || draftStatus === 'finished') && (
        <PokemonBrowser 
          selectedGen={selectedGen} 
          formatType={formatType}
          selectedTier={selectedTier}
          isDraftMode={true}
        />
      )}

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} />
      
      <TeraTypeModal />

      <footer className="bg-white border-t border-slate-200 mt-auto py-6">
        <div className="max-w-7xl mx-auto px-4 flex flex-col items-center gap-2">
          <p className="text-slate-500 text-xs text-center uppercase font-bold tracking-widest">
            Pokemon Point Buy Team Builder
          </p>
          <img 
            src="https://hits.dwyl.com/James-F-95/Pokemon-Point-Buy-Project.svg" 
            alt="Hits"
            className="h-5"
          />
        </div>
      </footer>
    </div>
  );
}

export default App;
