import React, { useState } from 'react';
import { Search, X, Zap, Info } from 'lucide-react';
import { useTeamStore } from '../store/useTeamStore';
import { useDraftStore } from '../store/useDraftStore';
import { getPokemonSpriteUrl } from '../utils/pokemonUtils';
import DraftInfoModal from './DraftInfoModal';

const PokemonBrowser = ({ selectedGen: propSelectedGen, formatType, selectedTier, isDraftMode = false }) => {
  const { pointList, updateMember, selectedMemberIndex, setIsBrowserOpen, team } = useTeamStore();
  const { 
    pickedPokemon, currentTurn, peerId, players, setPendingPick, draftTeams, 
    pointLimit, tierPoints, isRandomizedDraft, draftPool, isPityStunfisk, triggerPityPick,
    maxTeamSize, isCyclingDraft, selectedRuleSet, draftStatus, selectedGen: draftSelectedGen
  } = useDraftStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [isInfoModalOpen, setIsInfoModalOpen] = useState(false);

  const selectedGen = isDraftMode ? draftSelectedGen : propSelectedGen;

  const currentPointList = isRandomizedDraft && isDraftMode
    ? draftPool.reduce((acc, p) => { acc[p.name] = p; return acc; }, {})
    : (pointList[`${selectedGen}_${formatType}_${selectedTier || 'all'}`] || {});
  
  const myIndex = players.findIndex(p => p.id === peerId);
  const isMyTurn = isDraftMode && currentTurn === myIndex && myIndex !== -1;

  const getCost = (name, entry) => {
    if (isDraftMode) {
      // Use draft-specific tier points if available
      const shorthandTier = Object.keys(tierPoints).find(tier => {
        // This is a bit tricky because the entry might not have the tier name directly
        // But we can match the default cost from the entry if it's there
        return tierPoints[tier] === (typeof entry === 'object' ? entry.cost : entry);
      });
      if (shorthandTier) return tierPoints[shorthandTier];
    }
    return typeof entry === 'object' ? entry.cost : entry;
  };

  // Calculate current points for the player
  const currentTotalPoints = isDraftMode
    ? (myIndex !== -1 && draftTeams[myIndex] ? draftTeams[myIndex].reduce((sum, m) => sum + (m.cost || 0), 0) : 0)
    : team.members.reduce((sum, m) => sum + (m.cost || 0), 0);
  
  const currentPointLimit = isDraftMode ? pointLimit : team.pointLimit;

  const filteredPokemon = Object.entries(currentPointList)
    .filter(([name]) => name.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => a[0].localeCompare(b[0]));

  const canAffordAnything = filteredPokemon.some(([name, entry]) => {
    const isPicked = pickedPokemon.includes(name);
    const cost = getCost(name, entry);
    return !isPicked && (currentTotalPoints + cost <= currentPointLimit);
  });

  const showSaveMeButton = isDraftMode && isMyTurn && isPityStunfisk && !canAffordAnything;

  const handleSelect = (name, entry) => {
    const cost = getCost(name, entry);
    
    // Disallow if over budget
    if (currentTotalPoints + cost > currentPointLimit) {
      alert(`This Pokemon costs ${cost} points, which would put you over your budget of ${currentPointLimit}!`);
      return;
    }

    if (isDraftMode) {
      if (!isMyTurn || pickedPokemon.includes(name)) return;
      
      const id = typeof entry === 'object' ? entry.id : null;
      setPendingPick({ name, cost, id });
      return;
    }

    const id = typeof entry === 'object' ? entry.id : null;
    updateMember(selectedMemberIndex, { name, cost, id });
    setIsBrowserOpen(false);
  };

  return (
    <div className={isDraftMode ? (draftStatus === 'finished' ? "hidden" : "w-full mt-8") : "fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"}>
      <div className={isDraftMode 
        ? "bg-white rounded-2xl border border-slate-200 shadow-sm w-full max-h-[600px] flex flex-col" 
        : "bg-white rounded-lg shadow-xl w-full max-w-2xl max-h-[80vh] flex flex-col"
      }>
        <div className="p-4 border-b border-slate-200 flex items-center justify-between">
          <h2 className="text-lg font-bold flex items-center gap-2">
            {isDraftMode && <Zap size={18} className="text-blue-500" />}
            {isDraftMode ? "Draft Pool" : "Select Pokemon"}
          </h2>
          {!isDraftMode && (
            <button 
              onClick={() => setIsBrowserOpen(false)}
              className="p-1 hover:bg-slate-100 rounded-full transition-colors"
            >
              <X size={20} />
            </button>
          )}
        </div>

        <div className="p-4 border-b border-slate-200">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                autoFocus={!isDraftMode}
                type="text"
                placeholder="Search Pokemon..."
                className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            {isDraftMode && (
              <button
                onClick={() => setIsInfoModalOpen(true)}
                className="p-2 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-lg transition-colors flex items-center gap-2"
                title="Rules & Pricing"
              >
                <Info size={18} />
                <span className="text-xs font-bold hidden sm:inline">Rules</span>
              </button>
            )}
            {showSaveMeButton && (
              <button
                onClick={triggerPityPick}
                className="px-4 py-2 bg-yellow-500 hover:bg-yellow-600 text-white rounded-lg font-black text-xs uppercase shadow-sm transition-all flex items-center gap-2 animate-bounce"
              >
                <Zap size={14} /> Save me Stunfisk
              </button>
            )}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          {filteredPokemon.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {filteredPokemon.map(([name, entry]) => {
                const isPicked = pickedPokemon.includes(name);
                const cost = getCost(name, entry);
                const overBudget = currentTotalPoints + cost > currentPointLimit;
                
                return (
                  <button
                    key={name}
                    disabled={(isDraftMode && (!isMyTurn || isPicked)) || overBudget}
                    onClick={() => handleSelect(name, entry)}
                    className={`flex items-center justify-between p-3 rounded-lg border transition-all text-left ${
                      isPicked 
                        ? "bg-slate-50 border-slate-100 opacity-40 grayscale pointer-events-none" 
                        : (isDraftMode && !isMyTurn) || overBudget
                          ? "border-slate-200 opacity-60 grayscale cursor-not-allowed"
                          : "border-slate-200 hover:border-blue-400 hover:bg-blue-50 shadow-sm"
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center overflow-hidden border border-slate-100">
                        <img 
                          src={getPokemonSpriteUrl(entry.id || name)} 
                          alt={name}
                          className="w-full h-full object-contain"
                          loading="lazy"
                          onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = `https://img.pokemondb.net/sprites/home/normal/${name.toLowerCase().replace(/[^a-z0-9]/g, '-')}.png`;
                          }}
                        />
                      </div>
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-700 text-sm leading-tight">{name}</span>
                        {isPicked && <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Picked</span>}
                        {overBudget && !isPicked && <span className="text-[10px] text-red-400 font-bold uppercase tracking-widest">Too Expensive</span>}
                      </div>
                    </div>
                    <span className={`px-2 py-0.5 rounded text-[10px] font-black ${
                      overBudget && !isPicked ? "bg-red-100 text-red-700" : "bg-blue-100 text-blue-700"
                    }`}>
                      {cost}
                    </span>
                  </button>
                );
              })}
            </div>
          ) : (
            <div className="text-center py-12 text-slate-500">
              {Object.keys(currentPointList).length === 0 
                ? "No point list found for this configuration. Please click 'Download Tiers' in the header."
                : "No Pokemon found matching your search."}
            </div>
          )}
        </div>
      </div>
      
      <DraftInfoModal 
        isOpen={isInfoModalOpen} 
        onClose={() => setIsInfoModalOpen(false)}
        settings={{
          pointLimit,
          maxTeamSize,
          tierPoints,
          isRandomizedDraft,
          isCyclingDraft,
          isPityStunfisk,
          selectedRuleSet
        }}
      />
    </div>
  );
};

export default PokemonBrowser;
