import React from 'react';
import { X } from 'lucide-react';
import { useDraftStore } from '../store/useDraftStore';

const TERA_TYPES = [
  'Normal', 'Fire', 'Water', 'Grass', 'Electric', 'Ice', 
  'Fighting', 'Poison', 'Ground', 'Flying', 'Psychic', 'Bug', 
  'Rock', 'Ghost', 'Dragon', 'Steel', 'Fairy', 'Dark', 'Stellar'
];

const TeraTypeModal = () => {
  const { isTeraModalOpen, pendingPick, makePick, closeTeraModal } = useDraftStore();

  if (!isTeraModalOpen || !pendingPick) return null;

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col animate-in fade-in zoom-in duration-200">
        <div className="p-4 border-b border-slate-200 flex items-center justify-between bg-slate-50 rounded-t-xl">
          <h2 className="text-lg font-bold text-slate-800">Select Tera Type</h2>
          <button 
            onClick={closeTeraModal}
            className="p-1 hover:bg-slate-200 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-6">
          <div className="flex items-center gap-4 mb-6 p-3 bg-blue-50 rounded-lg border border-blue-100">
            <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center overflow-hidden border border-blue-200">
              <img 
                src={`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/home/${pendingPick.id}.png`} 
                alt={pendingPick.name}
                className="w-full h-full object-contain"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = `https://img.pokemondb.net/sprites/home/normal/${pendingPick.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}.png`;
                }}
              />
            </div>
            <div>
              <p className="font-bold text-slate-800">{pendingPick.name}</p>
              <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Choose its Tera Type for the draft</p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2">
            {TERA_TYPES.map((type) => (
              <button
                key={type}
                onClick={() => makePick(pendingPick.name, pendingPick.cost, pendingPick.id, type)}
                className="py-2 px-1 text-xs font-bold rounded-lg border border-slate-200 hover:border-blue-400 hover:bg-blue-50 transition-all text-slate-600 hover:text-blue-700 uppercase tracking-tighter"
              >
                {type}
              </button>
            ))}
          </div>
        </div>

        <div className="p-4 border-t border-slate-100 bg-slate-50 rounded-b-xl flex justify-end">
          <button 
            onClick={closeTeraModal}
            className="px-4 py-2 text-sm font-semibold text-slate-500 hover:text-slate-700 transition-colors"
          >
            Cancel Pick
          </button>
        </div>
      </div>
    </div>
  );
};

export default TeraTypeModal;
