import React from 'react';
import { Award, Download, Users, Copy, Check } from 'lucide-react';
import { useDraftStore } from '../store/useDraftStore';
import { getPokemonSpriteUrl } from '../utils/pokemonUtils';

const DraftFinishedScreen = () => {
  const { draftTeams, players, pointLimit } = useDraftStore();
  const [copiedIndex, setCopiedIndex] = React.useState(null);

  const calculatePoints = (team) => team.reduce((sum, m) => sum + (m.cost || 0), 0);

  const handleExportTeam = (team, playerIndex) => {
    const playerName = players[playerIndex]?.name || `Player ${playerIndex + 1}`;
    const exportText = team
      .filter(m => m.name)
      .map(m => {
        let text = `${m.name}`;
        if (m.item) text += ` @ ${m.item}`;
        text += `\nAbility: ${m.ability || 'None'}\n`;
        if (m.teraType) text += `Tera Type: ${m.teraType}\n`;
        if (m.moves) {
          m.moves.filter(move => move).forEach(move => {
            text += `- ${move}\n`;
          });
        }
        return text;
      })
      .join('\n');

    navigator.clipboard.writeText(exportText);
    setCopiedIndex(playerIndex);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-12 space-y-12 animate-in fade-in zoom-in duration-500">
      <div className="text-center space-y-4">
        <div className="inline-flex items-center justify-center w-20 h-20 bg-yellow-100 text-yellow-600 rounded-full mb-4 shadow-inner">
          <Award size={48} />
        </div>
        <h1 className="text-4xl font-black text-slate-800 tracking-tight uppercase">Draft Complete!</h1>
        <p className="text-slate-500 font-bold uppercase tracking-widest text-sm">Review final teams and export to Showdown</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {draftTeams.map((team, i) => {
          const playerName = players[i]?.name || `Player ${i + 1}`;
          const points = calculatePoints(team);
          
          return (
            <div key={i} className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden flex flex-col transition-all hover:shadow-2xl hover:-translate-y-1">
              <div className="p-6 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                <div>
                  <h3 className="text-lg font-black text-slate-800 uppercase leading-none mb-1">{playerName}</h3>
                  <p className={`text-xs font-bold ${points > pointLimit ? 'text-red-500' : 'text-slate-400'} uppercase tracking-tighter`}>
                    {points} / {pointLimit} Points used
                  </p>
                </div>
                <button 
                  onClick={() => handleExportTeam(team, i)}
                  className={`p-2 rounded-xl transition-all flex items-center gap-2 text-[10px] font-black uppercase ${
                    copiedIndex === i ? 'bg-green-500 text-white' : 'bg-white border border-slate-200 text-slate-600 hover:border-blue-400 hover:text-blue-600 shadow-sm'
                  }`}
                >
                  {copiedIndex === i ? <Check size={14} /> : <Copy size={14} />}
                  {copiedIndex === i ? 'Copied' : 'Export'}
                </button>
              </div>

              <div className="p-4 grid grid-cols-2 gap-3 flex-1">
                {team.map((member, j) => (
                  <div key={j} className="bg-slate-50 rounded-2xl p-3 border border-slate-100 flex flex-col items-center justify-center relative group overflow-hidden">
                    {member.name ? (
                      <>
                        <div className="absolute top-2 right-2 text-[8px] font-black text-slate-300 group-hover:text-blue-400 transition-colors">
                          {member.cost} PTS
                        </div>
                        <div className="w-16 h-16 mb-2 drop-shadow-md group-hover:scale-110 transition-transform">
                          <img 
                            src={getPokemonSpriteUrl(member.id || member.name)} 
                            alt={member.name}
                            className="w-full h-full object-contain"
                          />
                        </div>
                        <p className="text-[10px] font-black text-slate-700 text-center leading-tight uppercase truncate w-full">{member.name}</p>
                        {member.teraType && (
                          <span className="mt-1 px-1.5 py-0.5 bg-slate-800 text-white text-[7px] font-black rounded uppercase">
                            {member.teraType}
                          </span>
                        )}
                      </>
                    ) : (
                      <div className="text-slate-200 py-4"><Users size={24} opacity={0.5} /></div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <div className="flex justify-center pt-8">
        <button 
          onClick={() => window.location.reload()}
          className="px-8 py-4 bg-slate-800 hover:bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-lg transition-all flex items-center gap-3"
        >
          Return to Lobby
        </button>
      </div>
    </div>
  );
};

export default DraftFinishedScreen;