import { create } from 'zustand';
import Peer from 'peerjs';
import { DRAFT_RULESETS, getTierCategory } from '../constants/draftRules';
import { useTeamStore } from './useTeamStore';

const createInitialTeamMembers = (size) => Array(size).fill(null).map(() => ({
  name: '',
  cost: 0,
  item: '',
  ability: '',
  level: 100,
  teraType: '',
  moves: ['', '', '', ''],
  evs: { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 },
  ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31 },
  nature: 'Serious'
}));

// Helper for safe data sending
const safeSend = (conn, data) => {
  if (conn && conn.open) {
    conn.send(data);
  } else if (conn) {
    conn.on('open', () => conn.send(data));
  }
};

export const useDraftStore = create((set, get) => ({
  // PeerJS state
  peer: null,
  conns: [], // Array of connections for multiple players
  peerId: '',
  hostId: '', // Added to track the host's ID on the client side
  isHost: false,
  draftStatus: 'idle', // idle, hosting, joining, connected, drafting, finished
  players: [], // { id, name, index }

  // Draft state
  draftTeams: [], // Dynamically sized: [team0, team1, ..., teamN]
  currentTurn: 0, // Index of the active player (0 to players.length - 1)
  pickedPokemon: [], // Array of names already picked
  pointLimit: 50,
  maxTeamSize: 6,
  
  // Randomized Draft Settings
  isRandomizedDraft: false,
  isCyclingDraft: false,
  isPityStunfisk: false,
  selectedGen: 'sv', // Added to sync generation across draft participants
  selectedRuleSet: 'balanced', // id from DRAFT_RULESETS
  customDraftSettings: {
    poolSize: 15,
    enforceTierDiversity: true,
    enforceTypeDiversity: false,
    balancedTiersOnly: false, // if true, only OU/OUBL for example
    isCyclingDraft: false,
    pityStunfisk: false,
  },
  draftPool: [], // [{ name, cost, id }]
  zeroCostPool: [], // Extra pool of every 0 cost pokemon for pity fallback
  
  tierPoints: {
    "Uber": 30,
    "OU": 12,
    "UUBL": 10,
    "UU": 8,
    "RUBL": 7,
    "RU": 6,
    "NUBL": 5,
    "NU": 4,
    "PUBL": 3,
    "PU": 2,
    "ZUBL": 1.5,
    "ZU": 1,
    "NFE": 0,
    "LC": 0,
    "AG": 40,
    "Untiered": 0,
    "DUber": 30,
    "DOU": 12,
    "DUU": 8,
    "VGC": 10
  },
  
  // Tera Type being selected
  isTeraModalOpen: false,
  pendingPick: null, // { name, cost, id }

  // Actions
  setRandomizedDraft: (active) => set({ isRandomizedDraft: active }),
  setCyclingDraft: (active) => set({ isCyclingDraft: active }),
  setPityStunfisk: (active) => set({ isPityStunfisk: active }),
  setSelectedGen: (gen) => set({ selectedGen: gen }),
  setSelectedRuleSet: (ruleSetId) => {
    const rule = DRAFT_RULESETS.find(r => r.id === ruleSetId);
    if (rule) {
      set({ 
        selectedRuleSet: ruleSetId,
        isCyclingDraft: rule.settings.isCyclingDraft || false,
        isPityStunfisk: rule.settings.pityStunfisk || false
      });
    } else {
      set({ selectedRuleSet: ruleSetId });
    }
  },
  setCustomDraftSettings: (settings) => set((state) => {
    const newState = { ...state.customDraftSettings, ...settings };
    return { 
      customDraftSettings: newState,
      isCyclingDraft: newState.isCyclingDraft !== undefined ? newState.isCyclingDraft : state.isCyclingDraft,
      isPityStunfisk: newState.pityStunfisk !== undefined ? newState.pityStunfisk : state.isPityStunfisk
    };
  }),

  generateNewPool: () => {
    const state = get();
    const teamStore = useTeamStore.getState();
    
    // Get the current point list from teamStore
    // Try to find the list that matches the current generation and format
    const { selectedGen, formatType = 'singles' } = state;
    const cacheKey = `${selectedGen}_${formatType}_all`;
    let pointList = teamStore.pointList[cacheKey];

    // Fallback: if 'all' is not found, try to find any list that matches the gen and format
    if (!pointList) {
      const fallbackKey = Object.keys(teamStore.pointList).find(key => 
        key.startsWith(`${selectedGen}_${formatType}_`)
      );
      if (fallbackKey) {
        pointList = teamStore.pointList[fallbackKey];
      }
    }

    // Last resort: pick the first available list
    if (!pointList) {
      const cacheKeys = Object.keys(teamStore.pointList);
      if (cacheKeys.length > 0) {
        pointList = teamStore.pointList[cacheKeys[0]];
      }
    }

    // Final safety check: ensure pointList is an object and NOT just an entry or empty
    // If pointList has 'cost' or 'id' keys directly, it's likely an entry object, not a map of pokemon
    if (!pointList || Object.keys(pointList).length === 0 || pointList.cost !== undefined || pointList.id !== undefined) {
      console.warn('No valid point list found to generate pool from. Found:', pointList);
      return;
    }

    const ruleSet = state.selectedRuleSet === 'custom' 
      ? { settings: state.customDraftSettings }
      : DRAFT_RULESETS.find(r => r.id === state.selectedRuleSet);

    const settings = ruleSet.settings;
    const poolSize = settings.poolSize || 15;

    // To implement "Balanced Tiers" (all within 1 tier), we need a tier list
    const tierOrder = [
      "AG", "Uber", "OU", "UUBL", "UU", "RUBL", "RU", "NUBL", "NU", "PUBL", "PU", "ZUBL", "ZU", "Untiered"
    ];

    let allowedTiersForRound = null;
    if (settings.balancedTiersOnly) {
      // Pick a random base tier from those available in pointList
      const availableTiers = Array.from(new Set(Object.values(pointList).map(entry => {
        const cost = typeof entry === 'object' ? entry.cost : entry;
        return Object.keys(state.tierPoints).find(tier => state.tierPoints[tier] === cost);
      }))).filter(Boolean);
      
      if (availableTiers.length > 0) {
        const baseTier = availableTiers[Math.floor(Math.random() * availableTiers.length)];
        const baseIndex = tierOrder.indexOf(baseTier);
        
        if (baseIndex !== -1) {
          allowedTiersForRound = [
            tierOrder[baseIndex - 1],
            tierOrder[baseIndex],
            tierOrder[baseIndex + 1]
          ].filter(Boolean);
        } else {
          allowedTiersForRound = [baseTier];
        }
      }
    }

    const allPokemon = Object.entries(pointList)
      .filter(([name, entry]) => name !== 'cost' && name !== 'id' && name !== 'types') // Safety filter
      .map(([name, entry]) => ({
        name,
        cost: typeof entry === 'object' ? entry.cost : entry,
        id: typeof entry === 'object' ? entry.id : null,
        types: typeof entry === 'object' ? (entry.types || []) : [],
        isFullyEvolved: typeof entry === 'object' ? !!entry.isFullyEvolved : true // Default to true if not specified
      })).filter(p => {
      // Don't include already picked pokemon
      if (state.pickedPokemon.includes(p.name)) return false;
      
      // Filter for balancedTiersOnly if requested
      if (allowedTiersForRound) {
        const pokemonTier = Object.keys(state.tierPoints).find(tier => state.tierPoints[tier] === p.cost);
        if (!allowedTiersForRound.includes(pokemonTier)) return false;
      }
      
      return true;
    });

    let pool = [];

    // Function to check if a pokemon can be added based on type diversity
    const canAddWithTypeDiversity = (currentPool, pokemon) => {
      if (!settings.enforceTypeDiversity) return true;
      
      // Sort types to make comparison order-independent
      const pTypes = [...pokemon.types].sort().join(',');
      
      return !currentPool.some(existing => {
        const existingTypes = [...existing.types].sort().join(',');
        return pTypes === existingTypes;
      });
    };

    if (settings.ratios) {
      // Tier-Weighted Distribution
      const categories = { elite: [], high: [], mid: [], budget: [] };
      allPokemon.forEach(p => {
        categories[getTierCategory(p.cost)].push(p);
      });

      Object.entries(settings.ratios).forEach(([cat, count]) => {
        const available = [...categories[cat]];
        let addedInCat = 0;
        
        while (addedInCat < count && available.length > 0) {
          const randomIndex = Math.floor(Math.random() * available.length);
          const p = available.splice(randomIndex, 1)[0];
          
          if (canAddWithTypeDiversity(pool, p)) {
            pool.push(p);
            addedInCat++;
          }
        }
      });

      // Fill remaining slots if any
      const totalRequested = Object.values(settings.ratios).reduce((a, b) => a + b, 0);
      const targetCount = Math.min(poolSize, totalRequested);
      
      if (pool.length < targetCount) {
        const remaining = allPokemon.filter(p => !pool.find(pp => pp.name === p.name));
        const shuffledRemaining = [...remaining].sort(() => Math.random() - 0.5);
        
        for (const p of shuffledRemaining) {
          if (pool.length >= targetCount) break;
          if (canAddWithTypeDiversity(pool, p)) {
            pool.push(p);
          }
        }
      }
    } else if (settings.costAveraging) {
      // Cost-Averaging Pool
      const targetAvg = (state.pointLimit / state.maxTeamSize);
      const targetTotal = targetAvg * poolSize * 1.2;
      
      let currentTotal = 0;
      const shuffled = [...allPokemon].sort(() => Math.random() - 0.5);
      
      for (const p of shuffled) {
        if (pool.length < poolSize) {
          if (canAddWithTypeDiversity(pool, p)) {
            pool.push(p);
            currentTotal += p.cost;
          }
        } else break;
      }

      // Simple balancing: if too expensive, swap highest with a random lower cost
      if (currentTotal > targetTotal) {
        pool.sort((a, b) => b.cost - a.cost);
        const others = allPokemon.filter(p => !pool.find(pp => pp.name === p.name));
        for (let i = 0; i < pool.length && currentTotal > targetTotal; i++) {
          const budget = others.filter(p => p.cost < pool[i].cost);
          if (budget.length > 0) {
            // Find a replacement that respects type diversity
            const shuffledBudget = [...budget].sort(() => Math.random() - 0.5);
            const poolWithoutCurrent = pool.filter((_, idx) => idx !== i);
            
            const replacement = shuffledBudget.find(p => canAddWithTypeDiversity(poolWithoutCurrent, p));
            
            if (replacement) {
              currentTotal = currentTotal - pool[i].cost + replacement.cost;
              pool[i] = replacement;
            }
          }
        }
      }
    } else {
      // Basic random
      const shuffled = [...allPokemon].sort(() => Math.random() - 0.5);
      for (const p of shuffled) {
        if (pool.length >= poolSize) break;
        if (canAddWithTypeDiversity(pool, p)) {
          pool.push(p);
        }
      }
    }

    set({ draftPool: pool });

    // Populate the zero cost pool as a hidden extra for pity stunfisk fallback
    const allZeroCost = Object.entries(pointList)
      .filter(([name, entry]) => {
        const cost = typeof entry === 'object' ? entry.cost : entry;
        return name !== 'cost' && name !== 'id' && name !== 'types' && cost === 0;
      })
      .map(([name, entry]) => ({
        name,
        cost: 0,
        id: typeof entry === 'object' ? entry.id : null
      }));
    set({ zeroCostPool: allZeroCost });

    // Sync pool to others if host
    if (state.isHost) {
      state.conns.forEach(conn => {
        safeSend(conn, { type: 'SYNC_POOL', payload: pool });
      });
      
      // Check if current player needs pity gift after pool refresh
      get().checkPityStunfisk();
    }
  },

  triggerPityPick: () => {
    const { isPityStunfisk, currentTurn, draftTeams, pointLimit, draftPool, pickedPokemon, players, draftStatus, zeroCostPool, isHost, peerId, conns, handleRemotePick } = get();
    
    // Safety check: only the active player (or host on their behalf) should trigger this
    const myIndex = players.findIndex(p => p.id === peerId);
    if (!isPityStunfisk || draftStatus !== 'drafting' || currentTurn !== myIndex) return;

    const playerTeam = draftTeams[currentTurn];
    if (!playerTeam) return;

    const currentPoints = playerTeam.reduce((sum, m) => sum + (m.cost || 0), 0);
    const budgetLeft = pointLimit - currentPoints;
    const emptySlots = playerTeam.filter(m => !m.name).length;

    if (emptySlots === 0) return;

    // Get pointList to find Stunfisk data
    const teamStore = useTeamStore.getState();
    const { formatType = 'singles' } = teamStore;
    const { selectedGen } = get();
    const cacheKey = `${selectedGen}_${formatType}_all`;
    const pointList = teamStore.pointList[cacheKey] || {};

    const findStunfisk = (name) => {
      // First look in the draft pool itself if it was already generated
      const inPool = draftPool.find(p => p.name === name);
      if (inPool) return inPool;

      // Try fuzzy matching or common variations
      const possibleNames = [
        name,
        name.replace('-', ' '),
        name.replace(' ', '-'),
        name.replace('-Galar', ' Galar'),
        name.replace(' Galar', '-Galar'),
        name.replace('-Galar', '-G'),
        name.replace(' Galar', ' G'),
        name.charAt(0).toUpperCase() + name.slice(1).toLowerCase()
      ];

      for (const n of possibleNames) {
        const entry = pointList[n];
        if (entry) {
          console.log(`[DEBUG_LOG] Found ${name} as ${n} in pointList`);
          return {
            name: n,
            cost: typeof entry === 'object' ? entry.cost : entry,
            id: typeof entry === 'object' ? entry.id : null
          };
        }
      }

      // Final attempt: case-insensitive search
      const lowerName = name.toLowerCase();
      const foundKey = Object.keys(pointList).find(k => k.toLowerCase() === lowerName);
      if (foundKey) {
        const entry = pointList[foundKey];
        console.log(`[DEBUG_LOG] Found ${name} as ${foundKey} via case-insensitive search`);
        return {
          name: foundKey,
          cost: typeof entry === 'object' ? entry.cost : entry,
          id: typeof entry === 'object' ? entry.id : null
        };
      }

      return null;
    };

    const stunfisk = findStunfisk('Stunfisk');
    const gStunfisk = findStunfisk('Stunfisk-Galar');

    const playerHasStunfisk = playerTeam.some(m => m.name.toLowerCase().includes('stunfisk') && !m.name.toLowerCase().includes('galar'));
    const playerHasGStunfisk = playerTeam.some(m => m.name.toLowerCase().includes('stunfisk') && m.name.toLowerCase().includes('galar'));

    let gift = null;
    if (stunfisk && !playerHasStunfisk) {
      gift = stunfisk;
    } else if (gStunfisk && !playerHasGStunfisk) {
      gift = gStunfisk;
    }

    if (gift) {
      console.log(`[DEBUG_LOG] Triggering pity gift ${gift.name} for player ${players[currentTurn]?.name}`);
      const payload = { ...gift, teraType: 'Ground', playerIndex: currentTurn };
      
      if (isHost) {
        conns.forEach(c => safeSend(c, { type: 'PICK_POKEMON', payload }));
        handleRemotePick(payload);
      } else {
        const hostConn = conns[0]; 
        if (hostConn) {
          safeSend(hostConn, { type: 'PICK_POKEMON', payload });
        }
      }
    } else if ((playerHasStunfisk && playerHasGStunfisk) || (!stunfisk && !gStunfisk)) {
      console.log(`[DEBUG_LOG] Triggering random 0-cost Pokemon fallback.`);
      
      if (zeroCostPool.length > 0) {
        const randomGift = zeroCostPool[Math.floor(Math.random() * zeroCostPool.length)];
        console.log(`[DEBUG_LOG] Triggering random 0-cost ${randomGift.name} for player ${players[currentTurn]?.name}`);
        const payload = { ...randomGift, teraType: 'Normal', playerIndex: currentTurn };
        
        if (isHost) {
          conns.forEach(c => safeSend(c, { type: 'PICK_POKEMON', payload }));
          handleRemotePick(payload);
        } else {
          const hostConn = conns[0];
          if (hostConn) {
            safeSend(hostConn, { type: 'PICK_POKEMON', payload });
          }
        }
      } else {
        console.warn('Pity Stunfisk triggered, but no 0-cost Pokemon found in hidden pool!');
      }
    }
  },

  checkPityStunfisk: () => {
    const { isHost, isPityStunfisk, currentTurn, draftTeams, pointLimit, draftPool, pickedPokemon, players, draftStatus, zeroCostPool } = get();
    
    if (!isHost || !isPityStunfisk || draftStatus !== 'drafting') return;

    const playerTeam = draftTeams[currentTurn];
    if (!playerTeam) return;

    const currentPoints = playerTeam.reduce((sum, m) => sum + (m.cost || 0), 0);
    const budgetLeft = pointLimit - currentPoints;
    const emptySlots = playerTeam.filter(m => !m.name).length;

    if (emptySlots === 0) return;

    // Check if player can afford anything in the pool
    const availablePool = draftPool.filter(p => !pickedPokemon.includes(p.name));
    const affordable = availablePool.filter(p => p.cost <= budgetLeft);

    if (affordable.length === 0) {
      console.log(`[DEBUG_LOG] Player ${players[currentTurn]?.name} needs pity stunfisk (auto).`);
      
      // Get pointList to find Stunfisk data
      const teamStore = useTeamStore.getState();
      const { formatType = 'singles' } = teamStore;
      const { selectedGen } = get();
      const cacheKey = `${selectedGen}_${formatType}_all`;
      const pointList = teamStore.pointList[cacheKey] || {};

      const findStunfisk = (name) => {
        // First look in the draft pool itself if it was already generated
        const inPool = draftPool.find(p => p.name === name);
        if (inPool) return inPool;

        // Try fuzzy matching or common variations
        const possibleNames = [
          name,
          name.replace('-', ' '),
          name.replace(' ', '-'),
          name.replace('-Galar', ' Galar'),
          name.replace(' Galar', '-Galar'),
          name.replace('-Galar', '-G'),
          name.replace(' Galar', ' G'),
          name.charAt(0).toUpperCase() + name.slice(1).toLowerCase()
        ];

        for (const n of possibleNames) {
          const entry = pointList[n];
          if (entry) {
            console.log(`[DEBUG_LOG] Found ${name} as ${n} in pointList`);
            return {
              name: n,
              cost: typeof entry === 'object' ? entry.cost : entry,
              id: typeof entry === 'object' ? entry.id : null
            };
          }
        }

        // Final attempt: case-insensitive search
        const lowerName = name.toLowerCase();
        const foundKey = Object.keys(pointList).find(k => k.toLowerCase() === lowerName);
        if (foundKey) {
          const entry = pointList[foundKey];
          console.log(`[DEBUG_LOG] Found ${name} as ${foundKey} via case-insensitive search`);
          return {
            name: foundKey,
            cost: typeof entry === 'object' ? entry.cost : entry,
            id: typeof entry === 'object' ? entry.id : null
          };
        }

        return null;
      };

      const stunfisk = findStunfisk('Stunfisk');
      const gStunfisk = findStunfisk('Stunfisk-Galar');

      const playerHasStunfisk = playerTeam.some(m => m.name.toLowerCase().includes('stunfisk') && !m.name.toLowerCase().includes('galar'));
      const playerHasGStunfisk = playerTeam.some(m => m.name.toLowerCase().includes('stunfisk') && m.name.toLowerCase().includes('galar'));

      let gift = null;
      if (stunfisk && !playerHasStunfisk) {
        gift = stunfisk;
      } else if (gStunfisk && !playerHasGStunfisk) {
        gift = gStunfisk;
      }

      if (gift) {
        console.log(`[DEBUG_LOG] Gifting ${gift.name} to player ${players[currentTurn]?.name}`);
        const payload = { ...gift, teraType: 'Ground', playerIndex: currentTurn };
        get().conns.forEach(c => safeSend(c, { type: 'PICK_POKEMON', payload }));
        get().handleRemotePick(payload);
        
        // After giving one, check if they need another
        setTimeout(() => get().checkPityStunfisk(), 100);
      } else if ((playerHasStunfisk && playerHasGStunfisk) || (!stunfisk && !gStunfisk)) {
        // Player already has both, or neither could be found in pointList, gift a random 0-cost Pokemon
        // Using the hidden zeroCostPool instead of filtering the whole pointList here
        console.log(`[DEBUG_LOG] Gifting random 0-cost Pokemon fallback from zeroCostPool.`);
        
        if (zeroCostPool.length > 0) {
          const randomGift = zeroCostPool[Math.floor(Math.random() * zeroCostPool.length)];
          console.log(`[DEBUG_LOG] Gifting random 0-cost ${randomGift.name} to player ${players[currentTurn]?.name}`);
          const payload = { ...randomGift, teraType: 'Normal', playerIndex: currentTurn };
          get().conns.forEach(c => safeSend(c, { type: 'PICK_POKEMON', payload }));
          get().handleRemotePick(payload);
          setTimeout(() => get().checkPityStunfisk(), 100);
        } else {
          console.warn('Pity Stunfisk enabled, both Stunfisks owned, but no 0-cost Pokemon found in hidden pool!');
        }
      } else {
        console.warn('Pity Stunfisk enabled but no Pokemon (Stunfisk/G-Stunfisk/0-cost) available to gift!');
      }
    }
  },

  initHost: () => {
    // Reset any existing state before starting new host session
    get().resetDraft();
    const peer = new Peer(null, { 
      debug: 2,
      config: {
        'iceServers': [
          { 'urls': 'stun:stun.l.google.com:19302' },
          { 'urls': 'stun:stun1.l.google.com:19302' },
          { 'urls': 'stun:stun2.l.google.com:19302' },
          { 'urls': 'stun:stun3.l.google.com:19302' },
          { 'urls': 'stun:stun4.l.google.com:19302' },
          { 'urls': 'turn:openrelay.metered.ca:80', 'username': 'openrelayproject', 'credential': 'openrelayproject' },
          { 'urls': 'turn:openrelay.metered.ca:443', 'username': 'openrelayproject', 'credential': 'openrelayproject' },
          { 'urls': 'turn:openrelay.metered.ca:443?transport=tcp', 'username': 'openrelayproject', 'credential': 'openrelayproject' }
        ]
      }
    }); // Enable debug logging for PeerJS
    
    peer.on('open', (id) => {
      console.log('[DEBUG_LOG] Host peer opened with ID:', id);
      set({ 
        peer, 
        peerId: id, 
        hostId: id,
        isHost: true, 
        draftStatus: 'hosting',
        players: [{ id, name: 'Host', index: 0 }],
        conns: []
      });
    });

    peer.on('connection', (conn) => {
      console.log('[DEBUG_LOG] Host received incoming connection from:', conn.peer);
      // Small delay to ensure state is settled before handling connection
      setTimeout(() => {
        const currentConns = get().conns;
        // Check if connection already exists
        if (currentConns.find(c => c.peer === conn.peer)) {
          console.log('[DEBUG_LOG] Connection already exists for:', conn.peer);
          return;
        }

        if (currentConns.length >= 5) {
          console.log('[DEBUG_LOG] Room full. Rejecting:', conn.peer);
          safeSend(conn, { type: 'ERROR', payload: 'Room is full' });
          setTimeout(() => conn.close(), 1000);
          return;
        }

        set((state) => ({ 
          conns: [...state.conns, conn],
          draftStatus: 'connected'
        }));
        console.log('[DEBUG_LOG] Host added connection. Total:', get().conns.length);
        get().setupConnection(conn);
      }, 100);
    });

    peer.on('error', (err) => {
      console.error('Peer error:', err);
      if (err.type !== 'peer-unavailable') {
        alert('PeerJS error: ' + err.type);
        set({ draftStatus: 'idle' });
      }
    });
  },

  joinRoom: (id) => {
    // Reset any existing state before starting new join session
    get().resetDraft();
    const peer = new Peer(null, { 
      debug: 2,
      config: {
        'iceServers': [
          { 'urls': 'stun:stun.l.google.com:19302' },
          { 'urls': 'stun:stun1.l.google.com:19302' },
          { 'urls': 'stun:stun2.l.google.com:19302' },
          { 'urls': 'stun:stun3.l.google.com:19302' },
          { 'urls': 'stun:stun4.l.google.com:19302' },
          { 'urls': 'turn:openrelay.metered.ca:80', 'username': 'openrelayproject', 'credential': 'openrelayproject' },
          { 'urls': 'turn:openrelay.metered.ca:443', 'username': 'openrelayproject', 'credential': 'openrelayproject' },
          { 'urls': 'turn:openrelay.metered.ca:443?transport=tcp', 'username': 'openrelayproject', 'credential': 'openrelayproject' }
        ]
      }
    });
    
    peer.on('open', (myId) => {
      console.log('[DEBUG_LOG] Client peer opened with ID:', myId, 'Connecting to host:', id);
      const conn = peer.connect(id, { reliable: true }); // Request reliable connection
      set({ peer, peerId: myId, hostId: id, isHost: false, draftStatus: 'joining' });
      
      const handleOpen = () => {
        console.log('[DEBUG_LOG] Connection to host opened:', conn.peer);
        set({ conns: [conn], draftStatus: 'connected' });
        get().setupConnection(conn);
      };

      if (conn.open) {
        handleOpen();
      } else {
        conn.on('open', handleOpen);
      }

      conn.on('error', (err) => {
        console.error('[DEBUG_LOG] Connection error to host:', err);
        alert('Could not connect to peer. Make sure the ID is correct and the host is active.');
        set({ draftStatus: 'idle' });
      });
    });

    peer.on('error', (err) => {
      console.error('[DEBUG_LOG] Peer error on client:', err);
      if (err.type === 'peer-unavailable') {
        alert('Room not found. Please check the ID.');
      }
      set({ draftStatus: 'idle' });
    });
  },

  setupConnection: (conn) => {
    const handleReady = () => {
      console.log('[DEBUG_LOG] Connection ready with:', conn.peer);
      if (!get().isHost) {
        console.log('[DEBUG_LOG] I am client. Sending PLAYER_JOINED to host:', conn.peer);
        // Add a small delay to ensure host is ready for data
        setTimeout(() => {
          safeSend(conn, { type: 'PLAYER_JOINED' });
        }, 500);
      } else {
        console.log('[DEBUG_LOG] I am host. Waiting for PLAYER_JOINED from client:', conn.peer);
      }
    };

    if (conn.open) {
      handleReady();
    } else {
      conn.on('open', handleReady);
    }

    conn.on('data', (data) => {
      console.log('[DEBUG_LOG] Received data from', conn.peer, ':', data);
      const { type, payload } = data;
      
      // Host acts as a relay for all messages in a star network
      if (get().isHost) {
        get().conns.forEach(c => {
          if (c.peer !== conn.peer) {
            console.log('[DEBUG_LOG] Host relaying data to:', c.peer);
            safeSend(c, data);
          }
        });
      }

      switch (type) {
        case 'PLAYER_JOINED':
          console.log('[DEBUG_LOG] Processing PLAYER_JOINED from:', conn.peer);
          if (get().isHost) {
            // Check if player already exists to avoid duplicates
            const currentPlayers = get().players;
            const existingPlayer = currentPlayers.find(p => p.id === conn.peer);
            if (existingPlayer) {
              console.log('[DEBUG_LOG] Player already in list, re-sending SYNC_PLAYERS to all:', conn.peer);
              const updateMsg = { type: 'SYNC_PLAYERS', payload: currentPlayers };
              get().conns.forEach(c => safeSend(c, updateMsg));
              return;
            }

            const newPlayers = [...currentPlayers, { 
              id: conn.peer, 
              name: `Player ${currentPlayers.length + 1}`, 
              index: currentPlayers.length 
            }];
            console.log('[DEBUG_LOG] Host updated players list:', newPlayers);
            set({ players: newPlayers });
            
            // Broadcast full player list to everyone
            const updateMsg = { type: 'SYNC_PLAYERS', payload: newPlayers };
            console.log('[DEBUG_LOG] Host broadcasting SYNC_PLAYERS to all clients');
            get().conns.forEach(c => {
              console.log('[DEBUG_LOG] Sending SYNC_PLAYERS to:', c.peer);
              safeSend(c, updateMsg);
            });
          }
          break;
        case 'SYNC_PLAYERS':
          console.log('[DEBUG_LOG] Syncing players locally:', payload);
          set({ players: payload });
          // If I'm a client and I just received a sync, make sure my hostId is correct
          if (!get().isHost && payload.length > 0) {
            set({ hostId: payload[0].id });
          }
          break;
        case 'START_DRAFT':
          const teamsCount = payload?.playersCount || get().players.length;
          const currentMaxTeamSize = payload?.maxTeamSize || get().maxTeamSize;
          const freshTeams = Array(teamsCount).fill(null).map(() => createInitialTeamMembers(currentMaxTeamSize));
          set({ 
            draftStatus: 'drafting', 
            currentTurn: 0, 
            pickedPokemon: [], 
            draftTeams: freshTeams 
          });

          // Check if first player needs pity gift right at start (for host)
          if (get().isHost) {
            get().checkPityStunfisk();
          }
          break;
        case 'PICK_POKEMON':
          get().handleRemotePick(payload);
          break;
        case 'SYNC_SETTINGS':
          set({ 
            pointLimit: payload.pointLimit,
            maxTeamSize: payload.maxTeamSize || 6,
            tierPoints: payload.tierPoints || get().tierPoints,
            selectedGen: payload.selectedGen || 'sv',
            isRandomizedDraft: payload.isRandomizedDraft,
            isCyclingDraft: payload.isCyclingDraft || false,
            isPityStunfisk: payload.isPityStunfisk || false,
            selectedRuleSet: payload.selectedRuleSet,
            customDraftSettings: payload.customDraftSettings
          });
          break;
        case 'SYNC_POOL':
          set({ draftPool: payload });
          break;
        case 'ERROR':
          alert('Server error: ' + payload);
          get().resetDraft();
          break;
        default:
          break;
      }
    });

    conn.on('close', () => {
      // Don't monitor for disconnects if the draft is finished
      const state = get();
      if (state.draftStatus === 'finished') {
        console.log('[DEBUG_LOG] A player left after the draft finished.');
        return;
      }
      
      alert('A player disconnected');
      set({ draftStatus: 'idle', conns: [] });
    });
  },

  startDraft: () => {
    const { conns, isHost, pointLimit, maxTeamSize, tierPoints, players, isRandomizedDraft, isCyclingDraft, isPityStunfisk, selectedGen, selectedRuleSet, customDraftSettings } = get();
    if (isHost) {
      if (isRandomizedDraft) {
        get().generateNewPool();
      }

      const latestState = get();
      const settingsData = { 
        type: 'SYNC_SETTINGS', 
        payload: { 
          pointLimit: latestState.pointLimit, 
          maxTeamSize: latestState.maxTeamSize, 
          tierPoints: latestState.tierPoints,
          selectedGen: latestState.selectedGen,
          isRandomizedDraft: latestState.isRandomizedDraft,
          isCyclingDraft: latestState.isCyclingDraft,
          isPityStunfisk: latestState.isPityStunfisk,
          selectedRuleSet: latestState.selectedRuleSet,
          customDraftSettings: latestState.customDraftSettings
        } 
      };
      conns.forEach(c => safeSend(c, settingsData));

      if (latestState.isRandomizedDraft) {
        const syncPoolData = { type: 'SYNC_POOL', payload: latestState.draftPool };
        conns.forEach(c => safeSend(c, syncPoolData));
      }

      const startData = { type: 'START_DRAFT', payload: { playersCount: players.length, maxTeamSize } };
      conns.forEach(c => safeSend(c, startData));

      const freshTeams = Array(players.length).fill(null).map(() => createInitialTeamMembers(maxTeamSize));
      set({ 
        draftStatus: 'drafting', 
        currentTurn: 0, 
        pickedPokemon: [], 
        draftTeams: freshTeams 
      });

      // Check if first player needs pity gift right at start
      get().checkPityStunfisk();
    }
  },

  handleRemotePick: (payload) => {
    const { name, cost, id, teraType, playerIndex } = payload;
    set((state) => {
      const newTeams = [...state.draftTeams];
      const playerTeam = [...newTeams[playerIndex]];
      
      const emptySlotIndex = playerTeam.findIndex(m => !m.name);
      if (emptySlotIndex !== -1) {
        playerTeam[emptySlotIndex] = {
          ...playerTeam[emptySlotIndex],
          name, cost, id, teraType
        };
      }
      
      newTeams[playerIndex] = playerTeam;
      
      const allDrafted = newTeams.every(t => t.every(m => m.name));
      if (allDrafted) {
        return {
          draftTeams: newTeams,
          pickedPokemon: [...state.pickedPokemon, name],
          draftStatus: 'finished'
        };
      }

      // Snake draft logic: 
      // Round 0 (picks 0 to N-1): 0, 1, 2, 3...
      // Round 1 (picks N to 2N-1): 3, 2, 1, 0...
      // Round 2 (picks 2N to 3N-1): 0, 1, 2, 3...
      const totalPicks = newTeams.reduce((sum, team) => sum + team.filter(m => m.name).length, 0);
      const playersCount = state.players.length;
      const currentRound = Math.floor(totalPicks / playersCount);
      const isRoundEnding = totalPicks % playersCount === 0;
      
      let nextTurn;
      if (isRoundEnding) {
        // We just finished a round, totalPicks is now at the start of next round
        // If currentRound is even (0, 2, 4...), it means we just finished an EVEN round (0, 2...) 
        // and are starting an ODD round (1, 3...).
        // Wait, if totalPicks = 4 and playersCount = 4, currentRound = 1.
        // Round 0 was 0,1,2,3. Pick 4 should be 3 (last player of round 0).
        if (currentRound % 2 === 1) {
          // Starting an odd round (1, 3, 5...) -> Start from the last player
          nextTurn = playersCount - 1;
        } else {
          // Starting an even round (0, 2, 4...) -> Start from the first player
          nextTurn = 0;
        }
      } else {
        // We are in the middle of a round
        const roundDirection = currentRound % 2 === 0 ? 1 : -1;
        nextTurn = state.currentTurn + roundDirection;
      }

      let triggerPoolCycle = false;
      if (state.isCyclingDraft && isRoundEnding) {
        triggerPoolCycle = true;
      }

      return {
        draftTeams: newTeams,
        pickedPokemon: [...state.pickedPokemon, name],
        currentTurn: nextTurn,
        triggerPoolCycle // Internal flag to handle pool generation outside set()
      };
    });

    // If I am host and pool is exhausted OR cycling draft triggered a refresh
    const newState = get();
    if (newState.isHost && newState.isRandomizedDraft) {
      const remainingInPool = newState.draftPool.filter(p => !newState.pickedPokemon.includes(p.name));
      const shouldCycle = newState.triggerPoolCycle || remainingInPool.length === 0;
      
      if (shouldCycle && newState.draftStatus !== 'finished') {
        get().generateNewPool();
      } else {
        // If we didn't cycle the pool, we still need to check for pity stunfisk for the next player
        get().checkPityStunfisk();
      }
    }
  },

  makePick: (name, cost, id, teraType) => {
    const { conns, isHost, currentTurn, peerId, players, isCyclingDraft } = get();
    const myIndex = players.findIndex(p => p.id === peerId);
    
    if (currentTurn !== myIndex || myIndex === -1) return;

    const payload = { name, cost, id, teraType, playerIndex: myIndex };
    conns.forEach(c => safeSend(c, { type: 'PICK_POKEMON', payload }));

    set((state) => {
      const newTeams = [...state.draftTeams];
      const playerTeam = [...newTeams[myIndex]];
      
      const emptySlotIndex = playerTeam.findIndex(m => !m.name);
      if (emptySlotIndex !== -1) {
        playerTeam[emptySlotIndex] = {
          ...playerTeam[emptySlotIndex],
          name, cost, id, teraType
        };
      }
      
      newTeams[myIndex] = playerTeam;
      
      const allDrafted = newTeams.every(t => t.every(m => m.name));
      if (allDrafted) {
        return {
          draftTeams: newTeams,
          pickedPokemon: [...state.pickedPokemon, name],
          draftStatus: 'finished',
          isTeraModalOpen: false,
          pendingPick: null
        };
      }

      // Snake draft logic
      const totalPicks = newTeams.reduce((sum, team) => sum + team.filter(m => m.name).length, 0);
      const playersCount = players.length;
      const currentRound = Math.floor(totalPicks / playersCount);
      const isRoundEnding = totalPicks % playersCount === 0;
      
      let nextTurn;
      if (isRoundEnding) {
        if (currentRound % 2 === 1) {
          nextTurn = playersCount - 1;
        } else {
          nextTurn = 0;
        }
      } else {
        const roundDirection = currentRound % 2 === 0 ? 1 : -1;
        nextTurn = state.currentTurn + roundDirection;
      }

      let triggerPoolCycle = false;
      if (isCyclingDraft && isRoundEnding) {
        triggerPoolCycle = true;
      }

      return {
        draftTeams: newTeams,
        pickedPokemon: [...state.pickedPokemon, name],
        currentTurn: nextTurn,
        isTeraModalOpen: false,
        pendingPick: null,
        triggerPoolCycle
      };
    });

    // Handle pool refresh for host if they are the one making the pick
    const newState = get();
    if (newState.isHost && newState.isRandomizedDraft) {
      const remainingInPool = newState.draftPool.filter(p => !newState.pickedPokemon.includes(p.name));
      const shouldCycle = newState.triggerPoolCycle || remainingInPool.length === 0;

      if (shouldCycle && newState.draftStatus !== 'finished') {
        get().generateNewPool();
      } else {
        // If we didn't cycle the pool, we still need to check for pity stunfisk for the next player
        get().checkPityStunfisk();
      }
    }
  },

  setPendingPick: (pokemon) => set({ pendingPick: pokemon, isTeraModalOpen: true }),
  closeTeraModal: () => set({ isTeraModalOpen: false, pendingPick: null }),
  setPointLimit: (limit) => set({ pointLimit: limit }),
  
  applyConfig: (configBlob) => {
    try {
      const config = JSON.parse(configBlob);
      if (config.pointLimit) set({ pointLimit: config.pointLimit });
      if (config.maxTeamSize) set({ maxTeamSize: config.maxTeamSize });
      if (config.selectedGen) set({ selectedGen: config.selectedGen });
      // Note: tierPoints are used for cost lookups which happen on the client
      // but syncing them ensures the budget enforcement works correctly
      if (config.tierPoints) set({ tierPoints: config.tierPoints });
      
      // Additional randomized draft settings from JSON
      if (config.isRandomizedDraft !== undefined) set({ isRandomizedDraft: config.isRandomizedDraft });
      if (config.isCyclingDraft !== undefined) set({ isCyclingDraft: config.isCyclingDraft });
      if (config.isPityStunfisk !== undefined) set({ isPityStunfisk: config.isPityStunfisk });
      if (config.selectedRuleSet) set({ selectedRuleSet: config.selectedRuleSet });
      if (config.customDraftSettings) set((state) => ({ 
        customDraftSettings: { ...state.customDraftSettings, ...config.customDraftSettings } 
      }));

      const { conns, isHost, pointLimit, maxTeamSize, selectedGen, tierPoints, isRandomizedDraft, isCyclingDraft, isPityStunfisk, selectedRuleSet, customDraftSettings } = get();
      if (isHost && conns.length > 0) {
        const settingsData = { 
          type: 'SYNC_SETTINGS', 
          payload: { 
            pointLimit, 
            maxTeamSize, 
            selectedGen,
            tierPoints,
            isRandomizedDraft,
            isCyclingDraft,
            isPityStunfisk,
            selectedRuleSet,
            customDraftSettings
          } 
        };
        conns.forEach(c => safeSend(c, settingsData));
      }
      return true;
    } catch (err) {
      console.error('Error applying draft config:', err);
      return false;
    }
  },

  resetDraft: () => {
    const { peer, conns } = get();
    if (conns && conns.length > 0) {
      conns.forEach(c => {
        try { c.close(); } catch (e) {}
      });
    }
    if (peer) {
      try {
        peer.destroy();
      } catch (e) {
        console.error('Error destroying peer:', e);
      }
    }
    set({
      peer: null,
      conns: [],
      peerId: '',
      hostId: '',
      isHost: false,
      draftStatus: 'idle',
      players: [],
      draftTeams: [],
      currentTurn: 0,
      pickedPokemon: [],
      isTeraModalOpen: false,
      pendingPick: null
    });
  },
  
  setIsBrowserOpen: (isOpen) => {
    // This exists to satisfy the App.js call but we use it via standard store usually
  }
}));
