import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

const createInitialTeamMembers = (size) => Array(size).fill(null).map(() => ({
  name: '',
  cost: 0,
  item: '',
  ability: '',
  level: 100,
  teraType: '',
  moves: ['', '', '', ''],
  evs: { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 },
  ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31 },
  nature: 'Serious'
}));

export const useTeamStore = create(
  persist(
    (set) => ({
      team: {
        id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2),
        name: 'New Team',
        members: createInitialTeamMembers(6),
        pointLimit: 50, // Default point limit set to 50
        maxTeamSize: 6, // Default team size set to 6
      },
      pointList: {}, // Cache of pokemon data: { [gen_format_tier]: { name -> {cost, id} } }
      tierPoints: {
        "Uber": 30,
        "OU": 12,
        "UUBL": 10,
        "UU": 8,
        "RUBL": 7,
        "RU": 6,
        "NUBL": 5,
        "NU": 4,
        "PUBL": 3,
        "PU": 2,
        "ZUBL": 1.5,
        "ZU": 1,
        "NFE": 0,
        "LC": 0,
        "AG": 40,
        "Untiered": 0,
        "DUber": 30,
        "DOU": 12,
        "DUU": 8,
        "VGC": 10
      },
      tierLimits: {
        "Uber": false,
        "OU": false,
        "AG": false,
        "DUber": false,
        "DOU": false
      },
      formatType: 'singles', // 'singles' or 'doubles'
      isBrowserOpen: false,
      selectedMemberIndex: null,
      
      setTeam: (team) => set({ team }),
      setSelectedMemberIndex: (index) => set({ selectedMemberIndex: index, isBrowserOpen: index !== null }),
      setIsBrowserOpen: (isOpen) => set({ isBrowserOpen: isOpen }),
      
      updateMember: (index, memberUpdate) =>
        set((state) => {
          // Enforcement of tier limits
          if (memberUpdate.cost !== undefined) {
            // Find which tier this pokemon belongs to by looking at its cost in tierPoints
            const pokemonTier = Object.keys(state.tierPoints).find(tier => state.tierPoints[tier] === memberUpdate.cost);
            
            if (pokemonTier && state.tierLimits[pokemonTier]) {
              const otherOfSameTier = state.team.members.find((m, i) => {
                if (i === index || !m.name) return false;
                const otherCost = m.cost;
                const otherTier = Object.keys(state.tierPoints).find(tier => state.tierPoints[tier] === otherCost);
                return otherTier === pokemonTier;
              });

              if (otherOfSameTier) {
                alert(`You can only have one ${pokemonTier} on your team! (${otherOfSameTier.name} is already a ${pokemonTier})`);
                return state;
              }
            }
          }

          return {
            team: {
              ...state.team,
              members: state.team.members.map((m, i) => i === index ? { ...m, ...memberUpdate } : m)
            }
          };
        }),
        
      resetTeam: () => set((state) => ({
        team: {
          ...state.team,
          members: createInitialTeamMembers(state.team.maxTeamSize)
        }
      })),
        
      setPointList: (gen, format, tier, list) => set((state) => {
        const cacheKey = `${gen}_${format}_${tier || 'all'}`;
        const newPointList = { ...state.pointList, [cacheKey]: list };
        
        return { 
          pointList: newPointList,
          // When point list is updated, re-calculate costs for existing members if their names match
          team: {
            ...state.team,
            members: state.team.members.map(m => {
              const entry = list[m.name];
              return {
                ...m,
                cost: entry ? (typeof entry === 'object' ? entry.cost : entry) : 0,
                id: entry && typeof entry === 'object' ? entry.id : m.id
              };
            })
          }
        };
      }),
      
      setPointLimit: (limit) => set((state) => ({
        team: { ...state.team, pointLimit: limit }
      })),

      setMaxTeamSize: (size) => set((state) => {
        const newSize = Math.max(1, Math.min(12, size));
        let newMembers = [...state.team.members];
        
        if (newSize > newMembers.length) {
          // Add empty slots
          const extra = createInitialTeamMembers(newSize - newMembers.length);
          newMembers = [...newMembers, ...extra];
        } else if (newSize < newMembers.length) {
          // Truncate members
          newMembers = newMembers.slice(0, newSize);
        }

        return {
          team: { ...state.team, maxTeamSize: newSize, members: newMembers }
        };
      }),
      
      setFormatType: (formatType) => set({ formatType }),
      
      setTierPoints: (tierPoints) => set({ tierPoints }),
      
      setTierLimits: (tierLimits) => set({ tierLimits }),
    }),
    {
      name: 'pokemon-point-buy-storage', // name of the item in the storage (must be unique)
      storage: createJSONStorage(() => localStorage), // (optional) by default, 'localStorage' is used
      partialize: (state) => ({ 
        team: state.team, 
        pointList: state.pointList,
        tierPoints: state.tierPoints,
        tierLimits: state.tierLimits,
        formatType: state.formatType
      }),
    }
  )
);
